const dialogEscape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function choiceDialog(title,content,submit,prepare){return new Promise(resolve=>{const d=document.createElement('dialog');d.innerHTML='<form><h2>'+dialogEscape(title)+'</h2>'+content+'<div class="dialog-actions"><button class="secondary" type="button" data-cancel>Cancel</button><button class="primary" type="submit">'+dialogEscape(submit)+'</button></div></form>';document.body.append(d);let result=null;d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('form').onsubmit=e=>{e.preventDefault();result=prepare(d);if(result!==undefined)d.close();};d.onclose=()=>{resolve(result);d.remove();};d.showModal();});}
export const askText=(title,value='')=>choiceDialog(title,'<label class="dialog-input">Value<input name="answer" value="'+dialogEscape(value)+'" maxlength="2000"></label>','Continue',d=>d.querySelector('[name=answer]').value);
export const confirmAction=title=>choiceDialog('Confirm change','<p class="helper">'+dialogEscape(title)+'</p>','Confirm',()=>true);
export function chooseBulk(rows){return choiceDialog('Update '+rows.length+' selected records','<label class="dialog-input">Field<select name="field"><option value="assignedTo">Assigned worker</option><option value="due">Due date</option><option value="priority">Priority</option><option value="process">Manufacturing process</option><option value="material">Material</option><option value="subsystem">Subsystem</option></select></label><label class="dialog-input">New value<input name="value" maxlength="500" placeholder="Blank clears this field"></label><p class="helper">Applies only to these records. Material and process changes reset their related readiness checks.</p><div class="bulk-preview">'+rows.map(p=>'<p>'+dialogEscape(p.number)+' · '+dialogEscape(p.name)+'</p>').join('')+'</div>','Apply to selected records',d=>({key:d.querySelector('[name=field]').value,value:d.querySelector('[name=value]').value.trim()}));}
